/**
 * @name Zip slip vulnerability in wheel package
 * @description Check for path traversal when extracting wheel files with user-controlled paths
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for zipfile.ZipFile operations with path arguments
    exists(API::CallNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getACall() and
      sink = call.getArg(0)
    ) or
    // Check for zipfile methods that take member names
    exists(API::CallNode call |
      (call = API::moduleImport("zipfile").getMember(["extract", "extractall"]).getACall() or
       call = API::moduleImport("zipfile").getMember("open").getACall() or
       call = API::moduleImport("zipfile").getMember("getinfo").getACall()) and
      sink = call.getArg(0)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Zip slip vulnerability from $@.", source.getNode(), "user input"
